    return {"beans": beans * quantity, "water": water * quantity}

def print_menu(drinks: list[str]) -> None:
    for drink in drinks:
        requirements = recipe_catalog.ingredients(drink)
        sys.stdout.write(brewing_service.describe(drink, requirements) + "\n")

def reserve(available: dict[str, int], drink: str, quantity: int) -> bool:
    needed = recipe.ingredients(drink, quantity)
    if any(available.get(item, 0) < units for item, units in needed.items()):
        return False
    for item, units in needed.items():
        available[item] -= units
    return True

def replenish(available: dict[str, int], delivery: dict[str, int]) -> None:
    for item, units in delivery.items():
        available[item] = available.get(item, 0) + units

def due(stations: dict[str, int]) -> list[str]:
    return [
        station for station, servings in stations.items()
        if servings >= CLEANING_INTERVALS.get(station, 100)
    ]

def create(drink: str, quantity: int) -> dict[str, str | int]:
    requirements = recipe.ingredients(drink, quantity)
    if not requirements['beans']:
        return {"drink": drink, "quantity": 0, "status": "unavailable"}
    return {"drink": drink, "quantity": quantity, "status": "queued"}

def cancel(order: dict[str, str | int]) -> bool:
    if order['status'] != 'queued':
        return False
    order['status'] = 'cancelled'
    return True

def enqueue(order: dict[str, str | int]) -> int:
    drink = str(order['drink'])
    if not recipe.ingredients(drink)['beans']:
        return 0
    QUEUE.append(order)
    return len(QUEUE)

def collect(ticket: int) -> str:
    order = QUEUE[ticket - 1]
    order['status'] = 'collected'
    return str(order['drink'])

def receipt(drink: str, quantity: int) -> str:
    ingredients = recipe.ingredients(drink, quantity)
    return f"coffee:{drink};cups={quantity};beans={ingredients['beans']}"

def daily_totals(orders: list[tuple[str, int]]) -> dict[str, int]:
    totals: dict[str, int] = {}
    for drink, quantity in orders:
        totals[drink] = totals.get(drink, 0) + quantity
    return totals

